import{_ as s,a0 as u,w as p,s as b,I as l,x as e,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const B=JSON.parse('{"title":"Web 的成长，就是一篇浏览器的故事 | LCTT x X-CMD","titleTemplate":false,"description":"Web 的成长，就是一篇浏览器的故事 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Web 的成长，就是一篇浏览器的故事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Web 的成长，就是一篇浏览器的故事 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20190312 When the web grew up- A browser story","title":"Web 的成长，就是一篇浏览器的故事","tag":"202102","desc":""},"relativePath":"202102/20190312 When the web grew up- A browser story.md","filePath":"[post].md"}'),E={name:"202102/20190312 When the web grew up- A browser story.md"};function i(m,t,f,d,C,w){const n=u("Link");return p(),b("div",null,[t[27]||(t[27]=l("h1",{id:"web-的成长-就是一篇浏览器的故事",tabindex:"-1"},[e("Web 的成长，就是一篇浏览器的故事 "),l("a",{class:"header-anchor",href:"#web-的成长-就是一篇浏览器的故事","aria-label":"Permalink to “Web 的成长，就是一篇浏览器的故事”"},"​")],-1)),t[28]||(t[28]=l("blockquote",null,[l("p",null,"互联网诞生之时我的个人故事。")],-1)),t[29]||(t[29]=l("p",null,[l("img",{src:"https://img.linux.net.cn/data/attachment/album/202102/18/161753qb8tytkc6bnxbavn.jpg",alt:""})],-1)),l("p",null,[t[1]||(t[1]=e("最近，我和大家 ",-1)),r(n,{href:"https://opensource.com/article/18/11/how-web-was-won"},{default:o(()=>[...t[0]||(t[0]=[e("分享了",-1)])]),_:1}),t[2]||(t[2]=e(" 我在 1994 年获得英国文学和神学学位离开大学后，如何在一个人们还不知道 Web 服务器是什么的世界里成功找到一份运维 Web 服务器的工作。我说的“世界”，并不仅仅指的是我工作的机构，而是泛指所有地方。Web 那时当真是全新的 —— 人们还正尝试理出头绪。",-1))]),l("p",null,[t[4]||(t[4]=e("那并不是说我工作的地方（一家学术出版社）特别“懂” Web。这是个大部分人还在用 28.8K 猫（调制解调器，俗称“猫”）访问网页的世界。我还记得我拿到 33.6K 猫时有多激动。至少上下行速率不对称的日子已经过去了，",-1)),r(n,{href:"%E5%AE%83%E4%BB%AC%E5%8F%88%E6%98%AF%E6%80%8E%E4%B9%88%E5%9B%9E%E6%9D%A5%E7%9A%84%EF%BC%9F"},{default:o(()=>[...t[3]||(t[3]=[e("^1",-1)])]),_:1}),t[5]||(t[5]=e(" 以前 1200/300 的带宽描述特别常见。这意味着（在同一家机构的）印刷人员制作的设计复杂、色彩缤纷、纤毫毕现的文档是完全不可能放在 Web 上的。我不能允许在网站的首页出现大于 40k 的 GIF 图片，这对我们的许多访问者来说是很难接受的。大于大约 60k 图片的会作为独立的图片，以缩略图链接过去。",-1))]),l("p",null,[t[7]||(t[7]=e("如果说市场部只有这一点不喜欢，那是绝对是轻描淡写了。更糟的是布局问题。“浏览器决定如何布局文档，”我一遍又一遍地解释，“你可以使用标题或者段落，但是文档在页面上如何呈现并不取决于文档，而是取决于渲染器！”他们想控制这些，想要不同颜色的背景。后来明白了那些不能实现。我觉得我就像是参加了第一次讨论层叠样式表（CSS）的 W3C 会议，并进行了激烈地争论。关于文档编写者应控制布局的建议真令人厌恶。",-1)),r(n,{href:"%E4%BD%A0%E5%8F%AF%E8%83%BD%E4%B8%8D%E4%BC%9A%E6%83%8A%E8%AE%B6%EF%BC%8C%E6%88%91%E8%BF%98%E6%98%AF%E5%9C%A8%E5%91%BD%E4%BB%A4%E8%A1%8C%E9%87%8C%E6%9C%80%E5%BC%80%E5%BF%83%E3%80%82"},{default:o(()=>[...t[6]||(t[6]=[e("^2",-1)])]),_:1}),t[8]||(t[8]=e(" CSS 花了一些时间才被人们采用，与此同时，关心这些问题的人搭上了 PDF 这种到处都是安全问题的列车。",-1))]),t[30]||(t[30]=l("p",null,"如何呈现文档不是唯一的问题。作为一个实体书出版社，对于市场部来说，拥有一个网站的全部意义在于，让客户（或者说潜在的客户）不仅知道一本书的内容，而且知道买这本书需要花多少钱。但这有一个问题，你看，互联网，包括快速发展的万维网，是开放的，是所有都免费的自由之地，没有人会在意钱；事实上，在那里谈钱是要回避和避免的。",-1)),t[31]||(t[31]=l("p",null,"我和主流“网民”的看法一致，认为没必要把价格信息放在线上。我老板，以及机构里相当多的人都持相反的意见。他们觉得消费者应该能够看到书要花多少钱。他们也觉得我的银行经理也会想看到我的账户里每个月进了多少钱，如果我不认同他们的观点的话，那我的收入就可能堪忧。",-1)),l("p",null,[t[10]||(t[10]=e("幸运的是，在我被炒鱿鱼之前，我已经自己认清了一些 —— 可能是在我开始迈入 Web 的几星期之后，Web 已经发生变化，有其他人公布他们的产品价格信息。这些新来者通常被那些从早期就开始运行 Web 服务器的老派人士所看不起，",-1)),r(n,{href:"%E5%A4%A7%E7%BA%A6%E5%85%AD%E4%B8%AA%E6%9C%88%E5%89%8D%E3%80%82"},{default:o(()=>[...t[9]||(t[9]=[e("^3",-1)])]),_:1}),t[11]||(t[11]=e(" 但很明显，风向是往那边吹的。然而，这并不意味着我们的网站就赢得了战争。作为一个学术出版社，我们和大学共享一个域名（在 “ac.uk” 下）。大学不太相信发布价格信息是合适的，直到出版社的一些资深人士指出，普林斯顿大学出版社正在这样做，如果我们不做……看起来是不是有点傻？",-1))]),t[32]||(t[32]=l("p",null,"有趣的事情还没完。在我担任站点管理员（“webmaster@…”）的短短几个月后，我们和其他很多网站一样开始看到了一种令人担忧的趋势。某些访问者可以轻而易举地让我们的 Web 服务器跪了。这些访问者使用了新的网页浏览器：网景浏览器（Netscape）。网景浏览器实在太恶劣了，它居然是多线程的。",-1)),t[33]||(t[33]=l("p",null,"这为什么是个问题呢？在网景浏览器之前，所有的浏览器都是单线程。它们一次只进行一个连接，所以即使一个页面有五张 GIF 图，[^4] 也会先请求 HTML 基本文件进行解析，然后下载第一张 GIF，完成，接着第二张，完成，如此类推。事实上，GIF 的顺序经常出错，使得页面加载得非常奇怪，但这也是常规思路。而粗暴的网景公司的人决定，它们可以同时打开多个连接到 Web 服务器，比如说，可以同时请求所有的 GIF！为什么这是个问题呢？好吧，问题就在于大多数 Web 服务器都是单线程的。它们不是设计来一次进行多个连接的。确实，我们运行的 HTTP 服务的软件（MacHTTP）是单线程的。尽管我们花钱购买了它（最初是共享软件），但我们用的这版无法同时处理多个请求。",-1)),t[34]||(t[34]=l("p",null,"互联网上爆发了大量讨论。这些网景公司的人以为他们是谁，能改变世界的运作方式？它应该如何工作？大家分成了不同阵营，就像所有的技术争论一样，双方都用各种技术热词互丢。问题是，网景浏览器不仅是多线程的，它也比其他的浏览器更好。非常多 Web 服务器代码维护者，包括 MacHTTP 作者 Chuck Shotton 在内，开始坐下来认真地在原有代码基础上更新了多线程测试版。几乎所有人立马转向测试版，它们变得稳定了，最终，浏览器要么采用了这种技术，变成多线程，要么就像所有过时产品一样销声匿迹了。[^6]",-1)),t[35]||(t[35]=l("p",null,"对我来说，这才是 Web 真正成长起来的时候。既不是网页展示的价格，也不是设计者能定义你能在网页上看到什么，[^8] 而是浏览器变得更易用，以及成千上万的浏览者向数百万浏览者转变的网络效应，使天平向消费者而不是生产者倾斜。在我的旅程中，还有更多故事，我将留待下次再谈。但从这时起，我的雇主开始看我们的月报，然后是周报、日报，并意识到这将是一件大事，真的需要关注。",-1)),t[36]||(t[36]=l("p",null,"[^4]: 莽撞，没错，但它确实发生了 [^5] [^5]: 噢，不，是 GIF 或 BMP，JPEG 还是个好主意，但还没有用上。 [^6]: 没有真正的沉寂：总有一些坚持他们的首选解决方案具有技术上的优势，并哀叹互联网的其他人都是邪恶的死硬爱好者。 [^7] [^7]: 我不是唯一一个说“我还在用 Lynx”的人。 [^8]: 我会指出，为那些有各种无障碍需求的人制造严重而持续的问题。",-1)),t[37]||(t[37]=l("hr",null,null,-1)),l("p",null,[t[13]||(t[13]=e("via: ",-1)),r(n,{href:"https://opensource.com/article/19/3/when-web-grew"},{default:o(()=>[...t[12]||(t[12]=[e("https://opensource.com/article/19/3/when-web-grew",-1)])]),_:1})]),l("p",null,[t[18]||(t[18]=e("作者：",-1)),r(n,{href:"https://opensource.com/users/mikecamel"},{default:o(()=>[...t[14]||(t[14]=[e("Mike Bursell",-1)])]),_:1}),t[19]||(t[19]=e(" 选题：",-1)),r(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[15]||(t[15]=[e("lujun9972",-1)])]),_:1}),t[20]||(t[20]=e(" 译者：",-1)),r(n,{href:"https://github.com/XYenChi"},{default:o(()=>[...t[16]||(t[16]=[e("XYenChi",-1)])]),_:1}),t[21]||(t[21]=e(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[24]||(t[24]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[22]||(t[22]=[e("LCTT",-1)])]),_:1}),t[25]||(t[25]=e(" 原创编译，",-1)),r(n,{href:"https://linux.cn/"},{default:o(()=>[...t[23]||(t[23]=[e("Linux中国",-1)])]),_:1}),t[26]||(t[26]=e(" 荣誉推出",-1))])])}const T=s(E,[["render",i]]);export{B as __pageData,T as default};
